158	      const row: MedicationRow = {
159	        drug_name: m.picked_from_search?.display || m.name,
160	        status: stopped ? (held ? "held" : "stopped") : "active",
161	        patient_reported: true,
162	        evidence: [{ item_id: list.id, entry_id: eid }],
163	      };
164	      if (!multi && ing.names[0]) row.ingredient = ing.names[0];
165	      if (ing.rxnorm) row.rxnorm_ingredient = ing.rxnorm;
166	      const since = stopped ? m.stopped : m.started;
167	      if (typeof since === "string" && /^\d{4}(-\d{2}(-\d{2})?)?$/.test(since)) row.status_since = since;
168	      if (!multi) { const d = doseOf(m); if (d) row.dose = d; }
169	      const f = freqOf(m.how_i_take_it); if (f) row.frequency = f;
170	      if (stopped) {
171	        if (!held) { const r = stopReason(note); if (r) row.stop_reason = r; }
172	        if (note) row.status_reason_text = note;
173	      }
174	      if (m.kind === "over_the_counter") row.otc = true;
175	      const names = multi ? ing.names : [ing.names[0] ?? "\u0000" + seq];
176	      for (const n of names) {
177	        const r2: MedicationRow = multi ? { ...row, ingredient: n } : row;
178	        const key = (stopped ? m.stopped : m.started) ?? "";
179	        const prev = byIng.get(n);
180	        if (!prev || key >= prev.key) byIng.set(n, { key, row: r2 });
181	      }
182	    }
183	    rows.medications = [...byIng.values()].map((v) => v.row);
184	  }
185	
186	  // ── vitals: home readings
187	  type R = { t: number; row: VitalRow; device: boolean; sig: string };
188	  const readings: R[] = [];
189	  for (const it of cur) {
190	    for (const [eid, e] of Object.entries(it.payload ?? {}) as [string, any][]) {
191	      if (!e || typeof e.measured_at !== "string" || isNaN(minutes(e.measured_at))) continue;
192	      const ev = [{ item_id: it.id, entry_id: eid }];
193	      if (e.type === "bp_reading") {
194	        if (typeof e.systolic_mmhg !== "number" || typeof e.diastolic_mmhg !== "number") continue;
195	        const row: VitalRow = { setting: "home", local_time: e.measured_at.slice(0, 16), systolic_mmhg: e.systolic_mmhg, diastolic_mmhg: e.diastolic_mmhg, evidence: ev };
196	        if (typeof e.pulse_bpm === "number") row.pulse_bpm = e.pulse_bpm;
197	        readings.push({ t: minutes(e.measured_at), row, device: e.entry_method === "cuff_sync", sig: `bp${e.systolic_mmhg}/${e.diastolic_mmhg}` });
198	      } else if (e.type === "glucose_reading") {
199	        if (typeof e.value !== "number") continue;
200	        const mg = e.unit === "mmol/L" ? Math.round(e.value * 18.016) : e.unit === "mg/dL" ? Math.round(e.value) : NaN;
201	        if (isNaN(mg)) continue;
202	        const row: VitalRow = { setting: "home", local_time: e.measured_at.slice(0, 16), glucose_mg_dl: mg, evidence: ev };
203	        if (e.out_of_range === "HI" || e.out_of_range === "LO") row.glucose_out_of_range = e.out_of_range;
204	        readings.push({ t: minutes(e.measured_at), row, device: e.entry_method === "meter_sync", sig: `glu${mg}` });
205	      }
206	    }
207	  }
208	  const keep: R[] = [];
209	  for (const r of readings) {
210	    const dup = readings.find((o) => o !== r && o.sig === r.sig && o.device && !r.device && Math.abs(o.t - r.t) <= 3);
211	    if (!dup) keep.push(r);
212	  }
213	  keep.sort((a, b) => a.t - b.t);
214	  rows.vitals = keep.map((r) => r.row);
215	  return rows;
216	}
