import type { FolioItem, ViewRows, MedicationRow, VitalRow } from "../in/views/views";

const BRANDS: Record<string, string> = {
  zestril: "lisinopril", prinivil: "lisinopril", norvasc: "amlodipine", glucophage: "metformin",
