   */
  status: 'taking' | 'stopped';

  /** When the patient started it, from a month picker: `YYYY`, `YYYY-MM` or `YYYY-MM-DD`; precision is the string's precision. Absent if not entered. */
  started?: string;

  /** When the patient stopped it, same format as `started`. Present only when `status` is 'stopped', and not always then. */
  stopped?: string;

  /**
   * - 'prescription': the patient says a clinician prescribed it.
   * - 'over_the_counter': bought without a prescription (includes supplements).
   */
  kind: 'prescription' | 'over_the_counter';

  /** Patient's free-text note (why stopped, who prescribed, side effects). */
  note?: string;
}

